# ── gate: the machine is the one who decides ─────────────────────────
run_gate() {
  echo
  info "gate: verify + audit --ci"
  event --type gate --stage start
  node "$ENGINE" verify "$FEATURE"
  local v=$?
  event --type gate --stage verify --exit "$v"
  node "$ENGINE" audit --ci
  AUDIT=$?
  event --type gate --stage audit --exit "$AUDIT"
  # closes the books: task statuses + the verify proof in git
  if [ -n "$(git status --porcelain -- '.spec')" ]; then
    git add -A -- '.spec'
    git commit -q -m "$FEATURE: task statuses + verify proof (plan)"
    info "task statuses and verify proof committed"
  fi
  return "$AUDIT"
}

finish() { # $1=scope
  echo
  if [ -n "$FAILURES" ]; then red "tracks/tasks that failed:$FAILURES"; fi
  # without the gate there is no verdict: NEVER announce alignment without the audit
  if [ "$WITH_GATE" -eq 0 ]; then
    event --type end --exit 1 --scope "$1"
    if [ -z "$FAILURES" ]; then
      yellow "○ work on '$1' finished WITHOUT the gate (--no-gate) — this proves NOTHING"
      yellow "  for the verdict: bash .spec/features/credential-login-v1b/run-tasks.sh --gate"
      exit 0
    fi
    red "and there are still failures — fix them and run the gate"
    exit 1
  fi
  run_gate
  local audit=$?
  if [ "$audit" -eq 0 ] && [ -z "$FAILURES" ]; then
    event --type end --exit 0 --scope "$1"
    green "✔ plan done — spec and code aligned (audit exit 0) on branch $BASE_BRANCH"
    info "next step: review it and take it to main whenever you want (git merge $BASE_BRANCH)"
    exit 0
  fi
  event --type end --exit 1 --scope "$1"
  red "plan finished with open items — read the audit output above and the logs in $LOG_DIR"
  yellow "tip: re-run only what failed (--track <id> / --seq <T-xxx>)"
  exit 1
}

run_all() {
  event --type start --scope all
  start_summaries
  info "logs at: $LOG_DIR"
  info "overall progress summary: every 1 min here in the terminal (and via: onp-spec summary)"
  run_seq_T_014 || true
  run_seq_T_015 || true
  run_seq_T_016 || true
  run_seq_T_017 || true
  run_seq_T_018 || true
  run_seq_T_019 || true
  run_seq_T_020 || true
  run_seq_T_021 || true
  run_seq_T_022 || true
  run_seq_T_023 || true
  finish all
}

list_targets() {
  echo "run: $RUN_ID (feature $FEATURE, branch $BASE_BRANCH)"
  echo "  seq       T-014 (sequential)"
  echo "  seq       T-015 (sequential)"
  echo "  seq       T-016 (sequential)"
  echo "  seq       T-017 (sequential)"
  echo "  seq       T-018 (sequential)"
  echo "  seq       T-019 (sequential)"
  echo "  seq       T-020 (sequential)"
  echo "  seq       T-021 (sequential)"
  echo "  seq       T-022 (sequential)"
  echo "  seq       T-023 (sequential)"
  echo
  echo "re-run one track:      --track <id>"
  echo "re-run a sequential:   --seq <T-xxx>"
  echo "only the gate:         --gate"
}

MODE="all"
TARGET=""
while [ $# -gt 0 ]; do
  case "$1" in
    --list) MODE="list" ;;
    --gate) MODE="gate" ;;
    --no-gate) WITH_GATE=0 ;;
    --track) MODE="track"; TARGET="${2:-}"; shift ;;
    --seq) MODE="seq"; TARGET="${2:-}"; shift ;;
    -h|--help) sed -n "2,14p" "$0"; exit 0 ;;
    *) red "unknown argument: $1"; sed -n "2,14p" "$0"; exit 2 ;;
  esac
  shift
done

if [ "$MODE" = "list" ]; then list_targets; exit 0; fi

prepare_env

case "$MODE" in
  all) run_all ;;
  gate) WITH_GATE=1; start_summaries; finish gate ;;
  track)
    case "$TARGET" in
      *) fail "unknown track: '$TARGET' — see the available ones with --list" ;;
    esac ;;
  seq)
    case "$TARGET" in
      T-014) event --type start --scope "seq:T-014"; start_summaries; run_seq_T_014 || true; finish "seq:T-014" ;;
      T-015) event --type start --scope "seq:T-015"; start_summaries; run_seq_T_015 || true; finish "seq:T-015" ;;
      T-016) event --type start --scope "seq:T-016"; start_summaries; run_seq_T_016 || true; finish "seq:T-016" ;;
      T-017) event --type start --scope "seq:T-017"; start_summaries; run_seq_T_017 || true; finish "seq:T-017" ;;
      T-018) event --type start --scope "seq:T-018"; start_summaries; run_seq_T_018 || true; finish "seq:T-018" ;;
      T-019) event --type start --scope "seq:T-019"; start_summaries; run_seq_T_019 || true; finish "seq:T-019" ;;
      T-020) event --type start --scope "seq:T-020"; start_summaries; run_seq_T_020 || true; finish "seq:T-020" ;;
      T-021) event --type start --scope "seq:T-021"; start_summaries; run_seq_T_021 || true; finish "seq:T-021" ;;
      T-022) event --type start --scope "seq:T-022"; start_summaries; run_seq_T_022 || true; finish "seq:T-022" ;;
      T-023) event --type start --scope "seq:T-023"; start_summaries; run_seq_T_023 || true; finish "seq:T-023" ;;
      *) fail "unknown sequential task: '$TARGET' — see the available ones with --list" ;;
    esac ;;
esac
